import{_ as e,c as l,aU as a,a as i}from"./chunks/framework.DP-R0N-M.js";const y=JSON.parse('{"title":"租房","description":"","frontmatter":{},"headers":[],"relativePath":"note/rights_protection/zu-fang.md","filePath":"note/rights_protection/zu-fang.md","lastUpdated":1763220182000}'),d={name:"note/rights_protection/zu-fang.md"};function n(s,t,r,f,o,g){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="租房" tabindex="-1">租房 <a class="header-anchor" href="#租房" aria-label="Permalink to &quot;租房&quot;">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>租房是每个打工人的必修课，说真的，好房东的真少之又少，严格来说，我租了十几次房，就没见过退房租爽快的， 退的时候总是变着花样坑租客的钱，最常见的就是到期退，也打扫干净了，但是还说不干净，扣你几百的卫生费。 有的是住进去发现房子毛病一个接着一个，租给你了就撒手不管了，消息连带回都不回。 有的是提前退租，押金不要，但是剩余未住的房租也不退。 也不协商，消息不回装死，避重就轻，只拿合同说事，tmd房东的合同条款有一条是向着租客的？？？ 租客违约，扣租客的钱，假如房东违约呢？房东会给租客赔偿么？</p><p>当然，肯定是要有契约精神的，到期退，没啥问题的话，就给人家全额退。没啥可说的。 如果是提前退租，那就转租找下家，转租成功，给人家退押金，没找到那就押金不要呗。 但是我说的是，上面是基于房子本身是没有毛病的情况下，但是如果房子有很多毛病， 房东也不处理，那这种情况退租，我觉得押金和房租是需要退的。</p></div><table tabindex="0"><thead><tr><th style="text-align:left;">热线</th><th style="text-align:left;">主管部门</th><th style="text-align:left;">主要服务对象</th><th style="text-align:left;">典型使用场景</th></tr></thead><tbody><tr><td style="text-align:left;">12345</td><td style="text-align:left;">地方政府</td><td style="text-align:left;">全体市民/企业</td><td style="text-align:left;">投诉物业、咨询落户政策、举报环境污染</td></tr><tr><td style="text-align:left;">12368</td><td style="text-align:left;">最高人民法院</td><td style="text-align:left;">诉讼当事人/律师/公众</td><td style="text-align:left;">查询案件进度、联系法官、签收法律文书</td></tr><tr><td style="text-align:left;">12366</td><td style="text-align:left;">国家税务总局</td><td style="text-align:left;">纳税人/企业/缴费人</td><td style="text-align:left;">咨询个税申报、举报假发票、投诉税务人员</td></tr><tr><td style="text-align:left;">12315</td><td style="text-align:left;">市场监管总局</td><td style="text-align:left;">消费维权与市场违法举报</td><td style="text-align:left;">商品质量问题、价格欺诈、假货举报</td></tr><tr><td style="text-align:left;">96119</td><td style="text-align:left;">消防救援部门</td><td style="text-align:left;">火灾隐患举报与消防咨询</td><td style="text-align:left;">占用消防通道、消防设施损坏、违规施工</td></tr></tbody></table><ul><li>打12315 全国统一的消费者投诉举报专线电话</li><li>打12366 举报房东没开发票，偷税漏税</li><li>打96119 投诉房东消防不合格</li><li>【人民法院在线服务全国版】小程序 诉讼。</li><li>国务院客户端小程序投诉</li><li>浙江的朋友可以直接在浙里办上面，找到 民呼我为-我要反映，里面投诉 （亲测会受理，会打电话给房东，但是也只是协调）</li><li>打110 （亲测会受理，会打电话给房东，但是也只是协调）</li><li>【国家信访局】 小程序</li></ul>',4)])])}const c=e(d,[["render",n]]);export{y as __pageData,c as default};
